package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
)

type candidate struct {
	Language string `json:"language"`
	Path     string `json:"path"`
	Line     int    `json:"line"`
	Column   int    `json:"column"`
	Scope    string `json:"scope"`
	Name     string `json:"name"`
	RHS      string `json:"rhs"`
	Kind     string `json:"kind"`
}

var generatedMarkers = []string{
	"Code generated",
	"DO NOT EDIT",
	"AUTOGENERATED",
	"This file is generated",
}

func main() {
	rootDir := flag.String("root", defaultRootDir(), "Repository root.")
	includeGenerated := flag.Bool("include-generated", false, "Include generated files.")
	flag.Parse()

	files, err := trackedGoFiles(*rootDir, *includeGenerated)
	if err != nil {
		exitWithError(err)
	}

	candidates, err := scanGoFiles(*rootDir, files)
	if err != nil {
		exitWithError(err)
	}

	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(candidates); err != nil {
		exitWithError(err)
	}
}

func defaultRootDir() string {
	_, currentFile, _, ok := runtime.Caller(0)
	if !ok {
		return "."
	}
	return filepath.Clean(filepath.Join(filepath.Dir(currentFile), "..", ".."))
}

func trackedGoFiles(rootDir string, includeGenerated bool) ([]string, error) {
	command := exec.Command("git", "-C", rootDir, "ls-files", "-z")
	output, err := command.Output()
	if err != nil {
		return nil, err
	}

	files := []string{}
	for _, entry := range bytes.Split(output, []byte{0}) {
		if len(entry) == 0 {
			continue
		}
		relativePath := string(entry)
		if !strings.HasSuffix(relativePath, ".go") {
			continue
		}
		if !includeGenerated {
			generated, err := isGeneratedFile(rootDir, relativePath)
			if err != nil {
				return nil, err
			}
			if generated {
				continue
			}
		}
		files = append(files, relativePath)
	}
	sort.Strings(files)
	return files, nil
}

func scanGoFiles(rootDir string, files []string) ([]candidate, error) {
	fset := token.NewFileSet()
	candidates := []candidate{}

	for _, relativePath := range files {
		filePath := filepath.Join(rootDir, relativePath)
		fileNode, err := parser.ParseFile(fset, filePath, nil, parser.ParseComments)
		if err != nil {
			return nil, err
		}

		for _, decl := range fileNode.Decls {
			genDecl, ok := decl.(*ast.GenDecl)
			if !ok || genDecl.Tok != token.CONST {
				continue
			}
			for _, spec := range genDecl.Specs {
				valueSpec, ok := spec.(*ast.ValueSpec)
				if !ok || len(valueSpec.Values) == 0 {
					continue
				}
				if len(valueSpec.Values) != len(valueSpec.Names) {
					continue
				}
				for index, name := range valueSpec.Names {
					rhs, ok := goSimpleAliasExpr(valueSpec.Values[index])
					if !ok {
						continue
					}
					position := fset.Position(name.Pos())
					candidates = append(candidates, candidate{
						Language: "go",
						Path:     filepath.ToSlash(relativePath),
						Line:     position.Line,
						Column:   position.Column,
						Scope:    "package " + fileNode.Name.Name,
						Name:     name.Name,
						RHS:      rhs,
						Kind:     "go-const",
					})
				}
			}
		}
	}

	return candidates, nil
}

func goSimpleAliasExpr(expr ast.Expr) (string, bool) {
	switch typed := expr.(type) {
	case *ast.ParenExpr:
		return goSimpleAliasExpr(typed.X)
	case *ast.Ident:
		if typed.Name == "iota" || typed.Name == "true" || typed.Name == "false" {
			return "", false
		}
		return typed.Name, true
	case *ast.SelectorExpr:
		base, ok := goSimpleAliasExpr(typed.X)
		if !ok {
			return "", false
		}
		return base + "." + typed.Sel.Name, true
	default:
		return "", false
	}
}

func isGeneratedFile(rootDir string, relativePath string) (bool, error) {
	normalized := filepath.ToSlash(relativePath)
	if strings.Contains("/"+normalized+"/", "/generated/") {
		return true, nil
	}
	if strings.HasPrefix(normalized, "frontend/generation/") {
		return true, nil
	}

	content, err := os.ReadFile(filepath.Join(rootDir, relativePath))
	if err != nil {
		return false, err
	}
	header := string(content)
	if len(header) > 512 {
		header = header[:512]
	}
	for _, marker := range generatedMarkers {
		if strings.Contains(header, marker) {
			return true, nil
		}
	}
	return false, nil
}

func exitWithError(err error) {
	_, _ = os.Stderr.WriteString(err.Error() + "\n")
	os.Exit(1)
}
